import{z as o,x as s,o as e,c as d,q as t,j as r,D as A,d as l,s as i,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"区域合规与本地化","description":"","frontmatter":{"title":"区域合规与本地化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ml-regional-compliance.md","filePath":"llm/ml-regional-compliance.md","lastUpdated":1791413859000}'),m={name:"llm/ml-regional-compliance.md"};function p(D,E,C,F,u,h){const B=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=t('<h1 id="区域合规与本地化" tabindex="-1">区域合规与本地化 <a class="header-anchor" href="#区域合规与本地化" aria-label="Permalink to &quot;区域合规与本地化&quot;">​</a></h1><div class="epigraph"><p>合规不是把英文政策翻成二十种语言，而是把二十套法律映射到同一条产品流水线上。</p><footer>—— 据 GDPR（EU 2016/679）、EU AI Act（EU 2024/1689）、《生成式人工智能服务管理暂行办法》整理</footer></div><p><a href="/llm/ml-cultural-alignment">上一课</a>把规范分成全球政策与区域适配两层，区域层是软适配——猜错顶多失礼。接下来这一层是硬约束：法律。数据怎么存、往哪传、生成内容谁负责、哪些义务要备案审计，都按司法辖区生效，违反了不是分数下跌。本课写区域合规与本地化的工程架构：区域判定、政策分层、审计留痕。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一份全球产品在多辖区同时上线：欧盟要求数据出境走 GDPR 第五章的机制，AI 系统按风险分级履行透明度义务；中国的《生成式人工智能服务管理暂行办法》对生成式服务提出备案与内容责任要求；其他辖区各有数据驻留与消费者保护条款。工程问题有三个：区域判定——用户在哪、数据落哪、适用哪套规则；政策分层——哪些规则改系统提示、哪些改训练、哪些改产品流程；留痕——监管问询时能否出示证据。</p><p>三类常见错法。把合规当翻译：政策文档译成当地语言，行为不变。把合规当开关：一个「合规模式」布尔值，掩盖辖区间的真实差异。把合规当事后补丁：上线后按投诉打补丁，没有辖区映射表。</p><p><span class="marginnote">两个术语翻译：「数据驻留」指法律要求某些数据必须存在本国境内的服务器上，不许出门；「数据出境」则允许出门，但必须走法定通道——比如欧盟的标准合同条款。打个比方：驻留是「人不得离境」，出境机制是「可以离境但要先办签证」，两者对应完全不同的工程配置。</span></p><h3 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h3>',8)),(e(),r(n,null,{default:A(()=>[i(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20USER%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20REGION%5B%22%E5%8C%BA%E5%9F%9F%E5%88%A4%E5%AE%9A%EF%BC%9A%E8%B4%A6%E5%8F%B7%E3%80%81%E7%BD%91%E7%BB%9C%E3%80%81%E6%98%BE%E5%BC%8F%E5%A3%B0%E6%98%8E%22%5D%0A%20%20REGION%20--%3E%20RES%5B%22%E6%95%B0%E6%8D%AE%E9%A9%BB%E7%95%99%E4%B8%8E%E8%B7%A8%E5%A2%83%E4%BC%A0%E8%BE%93%E6%9C%BA%E5%88%B6%22%5D%0A%20%20REGION%20--%3E%20POLR%5B%22%E5%8C%BA%E5%9F%9F%E6%94%BF%E7%AD%96%E5%B1%82%EF%BC%9A%E6%8B%92%E7%AD%94%E8%BE%B9%E7%95%8C%E4%B8%8E%E6%8A%AB%E9%9C%B2%E4%B9%89%E5%8A%A1%22%5D%0A%20%20POLR%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%E4%B8%8E%E5%86%85%E5%AE%B9%E8%B4%A3%E4%BB%BB%E9%93%BE%22%5D%0A%20%20GEN%20--%3E%20AUD%5B%22%E5%AE%A1%E8%AE%A1%E7%95%99%E7%97%95%EF%BC%9A%E5%8C%BA%E5%9F%9F%E5%8C%96%E6%97%A5%E5%BF%97%E4%B8%8E%E7%89%88%E6%9C%AC%22%5D%0A%20%20RES%20--%3E%20AUD%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[l("区域判定要可解释：账号注册地、网络位置、显式选择的优先级写死并公告，因为同一次会话跨区域移动时适用规则会变。政策层与"),a("a",{href:"/llm/ml-cultural-alignment"},"文化对齐"),l("的规范层共用注入机制，但更新流程不同：文化层可以实验灰度，合规层要走法务评审与版本冻结。留痕要能回答三个问题：这条内容由哪个模型版本、哪套政策版本生成；数据存在哪个辖区；当时的拒答依据是哪一条。")],-1)),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"EU AI Act 于 2024 年 8 月生效，义务分阶段适用：禁止性条款自 2025 年 2 月起适用，通用目的模型义务自 2025 年 8 月起适用。同一产品在不同月份面对的义务清单不同，映射表必须带生效日期。")],-1)),E[5]||(E[5]=a("h2",{id:"方法",tabindex:"-1"},[l("方法 "),a("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),E[6]||(E[6]=a("p",null,"合规映射的本质是把法律谓词编译进流水线。每个辖区产出一组「谓词 → 措施」：数据出境要求 → 驻留与跨境传输机制（标准合同条款、出境评估）；内容责任与标识义务 → 生成管线里的披露与审核环节；透明度义务 → 模型卡与用户告知。谓词之间会重叠与冲突：删除权与日志保留义务可能同时适用，需要法务解释写成显式优先级，而不是留给自己在事故现场裁量。",-1)),(e(),r(n,null,{default:A(()=>[i(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAW%5B%22%E6%B3%95%E6%9D%A1%E5%8E%9F%E6%96%87%22%5D%20--%3E%20PRED%5B%22%E6%B3%95%E5%8A%A1%E7%BC%96%E8%AF%91%E6%88%90%E8%B0%93%E8%AF%8D%EF%BC%9A%E6%9D%A1%E4%BB%B6%E5%8A%A0%E4%B9%89%E5%8A%A1%22%5D%0A%20%20PRED%20--%3E%20CONFL%7B%22%E4%B8%A4%E6%9D%A1%E8%B0%93%E8%AF%8D%E5%86%B2%E7%AA%81%E5%90%97%EF%BC%9F%22%7D%0A%20%20CONFL%20--%3E%7C%22%E4%B8%8D%E5%86%B2%E7%AA%81%22%7C%20ACT%5B%22%E7%9B%B4%E6%8E%A5%E6%98%A0%E5%B0%84%E5%88%B0%E5%B7%A5%E7%A8%8B%E6%8E%AA%E6%96%BD%22%5D%0A%20%20CONFL%20--%3E%7C%22%E5%86%B2%E7%AA%81%EF%BC%8C%E5%A6%82%E5%88%A0%E9%99%A4%E6%9D%83%E5%AF%B9%E6%97%A5%E5%BF%97%E4%BF%9D%E7%95%99%22%7C%20PRIO%5B%22%E5%86%99%E6%98%BE%E5%BC%8F%E4%BC%98%E5%85%88%E7%BA%A7%E5%B9%B6%E6%B3%A8%E6%98%8E%E4%BE%9D%E6%8D%AE%22%5D%0A%20%20PRIO%20--%3E%20FREEZE%5B%22%E7%89%88%E6%9C%AC%E5%86%BB%E7%BB%93%E8%BF%9B%E6%98%A0%E5%B0%84%E8%A1%A8%22%5D%0A%20%20ACT%20--%3E%20FREEZE%0A%20%20FREEZE%20--%3E%20REGR%5B%22%E6%B3%95%E8%A7%84%E4%BF%AE%E8%AE%A2%E8%A7%A6%E5%8F%91%E5%90%88%E8%A7%84%E5%9B%9E%E5%BD%92%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p><span class="marginnote">「谓词」就是程序里的 if 条件：法务把法条翻译成「如果满足 X 条件，就必须做 Y」。举个例子：「用户是欧盟居民」是条件，「收到删除请求后 30 天内删除」是义务，合起来就是一条谓词。类比海关：法条是各国出入境法规，谓词表是海关窗口墙上那张「持 XX 护照请走 XX 通道」的对照牌——窗口员（工程流水线）照牌执行，不做现场立法。</span>语言识别在这里回归但角色反转（见<a href="/llm/langid-safety-filter">语言识别与安全过滤</a>）：说西语的用户可能在任何辖区，语言只能做体验路由，不能做合规判定；合规判定只认区域判定链。本地化的另一半是产品清单：计量单位、日期格式、医疗与法律资质声明、消费者保护措辞，与合规谓词分开管理、分别验收。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>这条架构的机制约束是「误判时的默认安全侧」。区域判定永远可能错：跨区网络与账号使判定可被绕过，所以义务设计按「判定错误时落在更严格的一侧」配置——这类似保守拒答的思路，但粒度是辖区。留痕之所以是机制而不是日志习惯，是因为合规义务的举证责任在服务方：一条生成的可回溯链（模型版本、政策版本、数据辖区、拒答依据）是唯一能同时应对三个辖区问询的证据形态。</p><p><span class="marginnote">常见误区：以为「用户说什么语言就适用哪国法律」。实际上说西语的用户可能人在美国、德国或阿根廷，适用规则完全不同；按语言做合规判定，等于把纽约的西语用户错配进拉美辖区的规则里。语言只能决定界面体验（菜单、术语、语气），辖区判定只认账号、网络位置与显式选择这条硬链。</span>验收口径也由此不同：这一课的验收标准不是平均分，而是「任一次生成可回溯到政策与模型版本」——与对齐评测的能力口径分开，两者不可互相替代。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>工程边界有三。第一，法规在移动：AI 立法在多辖区同步演进，映射表要带生效日期与版本，评测里加「合规回归」项，法规修订按版本触发。第二，合规映射不产生伦理：法律是底线，<a href="/llm/ml-cultural-alignment">文化对齐</a>的规范层可能比法律更严，两层不一致时取更严者并记录分歧。第三，本地化的深度有限度：术语、格式、披露可以逐区做，模型的核心行为不应该逐区分叉出不可审计的版本——分叉越多，留痕与回归的成本越高，出事时的解释链越长。合规团队要的是可审计的证据链，不是能力分数；这条边界决定了合规工程与评测工程的分工。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>合规按辖区生效：区域判定、政策分层、审计留痕是三件工程事实，不是文档翻译。</li><li>法律谓词编译成「谓词 → 措施」映射表，带生效日期与版本；冲突时写显式优先级。</li><li>文化层可实验，合规层走法务评审与版本冻结；两层共用注入机制但流程分离。</li><li>语言不是辖区的代理；语言路由只做体验，合规判定只认区域判定链，并按误判保守侧设计。</li><li>验收口径是可回溯性：任一次生成可指认模型版本、政策版本与数据辖区。</li><li>出处：GDPR (EU) 2016/679；Regulation (EU) 2024/1689 (AI Act)；《生成式人工智能服务管理暂行办法》，2023；PIPL 跨境条款。</li></ul>',8))])}const P=o(m,[["render",p]]);export{f as __pageData,P as default};
